import React, { useEffect } from 'react';
import { motion, useAnimation } from 'framer-motion';
import './Hero.css';

const Hero = () => {
  const controls = useAnimation();

  useEffect(() => {
    const sequence = async () => {
      await controls.start('visible');
    };
    sequence();
  }, [controls]);

  const textVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.8,
        ease: 'easeOut'
      }
    }
  };

  const steamVariants = {
    hidden: { opacity: 0, y: 10 },
    visible: {
      opacity: [0.3, 0.5, 0.3],
      y: -10,
      transition: {
        duration: 2,
        repeat: Infinity,
        ease: 'easeInOut'
      }
    }
  };

  return (
    <section className="hero" id="hero">
      <div className="hero-overlay"></div>
      <div className="container hero-content">
        <div className="coffee-animation">
          <div className="coffee-cup">
            <motion.div
              className="steam"
              initial="hidden"
              animate="visible"
              variants={steamVariants}
            >
              <span></span>
              <span></span>
              <span></span>
            </motion.div>
            <motion.img 
              src="/images/coffee-cup.svg" 
              alt="Coffee Cup" 
              className="cup-img"
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={{ duration: 0.8 }}
            />
          </div>
        </div>

        <motion.div
          className="hero-text"
          initial="hidden"
          animate={controls}
          variants={{
            hidden: { opacity: 0 },
            visible: {
              opacity: 1,
              transition: {
                staggerChildren: 0.3
              }
            }
          }}
        >
          <motion.h1 variants={textVariants}>
            Welcome to the Heart of Flavor ☕️🍰
          </motion.h1>
          
          <motion.p variants={textVariants}>
            Where every sip and bite tells a story.
          </motion.p>
          
          <motion.p variants={textVariants}>
            Explore our cozy cafe with a smooth blend of atmosphere and taste.
          </motion.p>
          
          <motion.p variants={textVariants}>
            Let's brew up something special together!
          </motion.p>

          <motion.div 
            className="cta-buttons"
            variants={textVariants}
          >
            <motion.a
              href="#menu"
              className="btn btn-primary"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              Explore Menu
            </motion.a>
            <motion.a
              href="#reservation"
              className="btn btn-secondary"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              Book a Table
            </motion.a>
          </motion.div>
        </motion.div>
      </div>

      <div className="scroll-indicator">
        <motion.div
          animate={{
            y: [0, 10, 0],
          }}
          transition={{
            duration: 1.5,
            repeat: Infinity,
            ease: "easeInOut"
          }}
        >
          <span className="scroll-arrow"></span>
          <span className="scroll-text">Scroll to explore</span>
        </motion.div>
      </div>
    </section>
  );
};

export default Hero;
